import { loadFont } from "@remotion/google-fonts/Sora";
import React, { forwardRef, useEffect, useId, useImperativeHandle, useLayoutEffect, useMemo, useRef, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

// Chrome parks a glyph raster on a whole pixel vertically for as long as the
// matrix that carries it is axis-aligned, so text under a slow transform
// clicks along pixel by pixel. A lean too small to see takes it off that grid.
//
// A transform that carries text is marked, and told when it moves:
//
//   const glide = useGlide();
//   transform: `scale(${s})${glide(moving)}`
//
// The mark changes nothing by itself. After every frame the blocks of text
// under a marked transform get the lean: each about its own centre, and each
// by no more than its size on the screen needs. A card, a hairline or an image
// is fine under a transform as it is, so they stay level.
//
// Text leans while its transform moves, and it keeps the lean at rest when it
// rests off the pixel grid (a scene shown smaller in a player, a camera that
// holds at 1.03): dropping the lean there would snap it to the nearest pixel,
// up to half a pixel in one frame, and picking it up would snap it back. Text
// that rests on the grid loses the lean without moving, so a scene at rest at
// full size is drawn exactly as it would be without any of this.

/**
 * Returns `glide(moving)`: append it to a transform that carries text, with
 * `moving` true on the frames where that transform changes.
 *
 * Everything else lives inside this one closure: the build of Studio
 * elements pastes this file whole into the component that uses it, where a
 * second `LEAN` or `lean` at the top level would collide.
 */
const useGlide = (() => {
  /** What `glide(false)` adds to a transform: an identity matrix, to find it by. */
  const AT_REST = " matrix(1, 0, 0, 1, 0, 0)";
  /** `glide(true)` adds it twice. */
  const MOVING = AT_REST + AT_REST;
  const MARKED = `[style*="${AT_REST.trim()}"]`;
  // Text leaves the grid once the matrix leans x into y by half of 1/1024 in
  // device pixels (Skia rounds the glyph matrix to 1/1024). A fifth over it.
  const LEAN = 0.6 / 1024;
  // Past this the text is a speck on the screen; it is left alone.
  const STEEPEST = 5;
  // How far from a whole pixel text may rest and still count as on the grid:
  // the jump it makes when the lean goes is no bigger than this.
  const ON_GRID = 0.05;

  /** The linear part of a 2D matrix: x' = a·x + c·y, y' = b·x + d·y. */
  type Lin = [a: number, b: number, c: number, d: number];
  const LEVEL: Lin = [1, 0, 0, 1];
  const times = (m: Lin, n: Lin): Lin => [
    m[0] * n[0] + m[2] * n[1],
    m[1] * n[0] + m[3] * n[1],
    m[0] * n[2] + m[2] * n[3],
    m[1] * n[2] + m[3] * n[3],
  ];
  const turned = (degrees: number): Lin => {
    const t = (degrees * Math.PI) / 180;
    return [Math.cos(t), Math.sin(t), -Math.sin(t), Math.cos(t)];
  };
  const offWhole = (n: number) => Math.abs(n - Math.round(n));

  type Block = HTMLElement | SVGTextElement | SVGSVGElement;
  let leant: Block[] = [];
  // Fonts arrive after the first pass and change what is laid out where, with
  // no render to follow: a block or a marked element that changes size is read
  // again before the frame is painted.
  let watcher: ResizeObserver | undefined;
  const watched = new WeakSet<Element>();
  const watch = (el: Element) => {
    if (watched.has(el)) return;
    watched.add(el);
    watcher ??= new ResizeObserver(() => lean());
    watcher.observe(el);
  };

  const depthOf = (el: Element) => {
    let depth = 0;
    for (let up = el.parentElement; up; up = up.parentElement) depth += 1;
    return depth;
  };

  /** The nearest box around a text node that a transform applies to. */
  const blockOf = (node: Node): Block | null => {
    for (let el = node.parentElement; el; el = el.parentElement) {
      if (el instanceof SVGElement) {
        const text = el.closest("text");
        if (!(text instanceof SVGTextElement)) return null;
        // Text that only shapes a mask or a clip is not drawn where it stands
        // and cannot turn by itself: its whole drawing leans for it.
        if (!text.closest("defs, mask, clipPath, pattern, symbol, marker"))
          return text;
        let drawing = text.ownerSVGElement;
        while (drawing?.ownerSVGElement) drawing = drawing.ownerSVGElement;
        return drawing;
      }
      if (!(el instanceof HTMLElement)) continue;
      const { display } = getComputedStyle(el);
      if (display !== "inline" && display !== "contents") return el;
    }
    return null;
  };

  /** One pass over the page: what every element's own transforms do. */
  function reader(given: Map<Element, number>) {
    type Own = {
      /** `scale` and `transform`, without the `rotate` property. */
      lin: Lin;
      /** `rotate`, in degrees: a lean given in this pass, or the scene's own. */
      turn: number;
      /** How far down it is moved, and by what whole factor it is scaled from
       * its top left corner; null when it does anything else. */
      carry: { dy: number; k: number } | null;
    };
    const lens = new Map<Element, boolean>();
    /** Whether an element shows its children in perspective. */
    const lensOn = (el: Element | null): boolean => {
      if (!el) return false;
      const seen = lens.get(el);
      if (seen !== undefined) return seen;
      const style = getComputedStyle(el);
      const result =
        style.perspective !== "none" ||
        (style.transformStyle === "preserve-3d" && lensOn(el.parentElement));
      lens.set(el, result);
      return result;
    };
    const own = new Map<Element, Own | null>();
    const ownOf = (el: Element): Own | null => {
      const seen = own.get(el);
      if (seen !== undefined) return seen;
      const style = getComputedStyle(el);
      const m = new DOMMatrixReadOnly(
        style.transform === "none" ? "" : style.transform,
      );
      const scale = style.scale === "none" ? [] : style.scale.split(" ");
      const sx = scale.length ? Number.parseFloat(scale[0]) : 1;
      const sy = scale.length > 1 ? Number.parseFloat(scale[1]) : sx;
      const rotate = style.rotate === "none" ? [] : style.rotate.split(" ");
      let result: Own | null = null;
      // Seen in perspective, text is drawn on a layer of its own: not ours. A
      // turn out of the plane without perspective lands flat on the screen,
      // and text under it snaps like any other.
      // A push along z alone, or a half turn, leaves it flat even under a lens.
      const inPerspective =
        Math.max(Math.abs(m.m14), Math.abs(m.m24), Math.abs(m.m34)) > 1e-9 ||
        (Math.max(
          Math.abs(m.m13),
          Math.abs(m.m31),
          Math.abs(m.m23),
          Math.abs(m.m32),
        ) > 1e-6 &&
          lensOn(el.parentElement));
      if (!inPerspective && rotate.length < 2) {
        // The `scale` property acts on what `transform` has produced.
        const lin: Lin = [m.a * sx, m.b * sy, m.c * sx, m.d * sy];
        const moved =
          style.translate === "none"
            ? 0
            : (style.translate.split(" ")[1] ?? "0px");
        const k = Math.round(lin[0]);
        const whole =
          m.is2D &&
          k >= 1 &&
          Math.abs(lin[0] - k) < 1e-4 &&
          Math.abs(lin[3] - k) < 1e-4 &&
          Math.abs(lin[1]) < 1e-5 &&
          Math.abs(lin[2]) < 1e-5 &&
          rotate.length === 0 &&
          (moved === 0 || moved.endsWith("px")) &&
          // Scaled about its corner, a box stays where layout put it.
          (k === 1 || /^0(px)? 0(px)?/.test(style.transformOrigin));
        result = {
          lin,
          turn: rotate.length ? Number.parseFloat(rotate[0]) : 0,
          carry: whole
            ? { dy: sy * m.f + (moved === 0 ? 0 : Number.parseFloat(moved)), k }
            : null,
        };
      }
      own.set(el, result);
      return result;
    };
    const down = new Map<Element, Lin | null>();
    /** Everything from the page down to and including this element. */
    const linDown = (el: Element | null): Lin | null => {
      if (!el) return LEVEL;
      const seen = down.get(el);
      if (seen !== undefined) return seen;
      const above = linDown(el.parentElement);
      const mine = above && ownOf(el);
      const result =
        above && mine
          ? times(times(above, turned(given.get(el) ?? mine.turn)), mine.lin)
          : null;
      down.set(el, result);
      return result;
    };
    const carried = new Map<Element, { dy: number; k: number } | null>();
    const carryDown = (
      el: Element | null,
    ): { dy: number; k: number } | null => {
      if (!el) return { dy: 0, k: 1 };
      const seen = carried.get(el);
      if (seen !== undefined) return seen;
      const above = carryDown(el.parentElement);
      const mine = above && !given.has(el) ? ownOf(el)?.carry : null;
      const result =
        above && mine
          ? { dy: above.dy + above.k * mine.dy, k: above.k * mine.k }
          : null;
      carried.set(el, result);
      return result;
    };
    return { ownOf, linDown, carryDown };
  }

  /**
   * Whether text in an SVG rests on the grid: it is placed wherever it is told
   * to, so only when it is shown one to one and its baseline happens to land on
   * a whole pixel. `lands` is where its own space lands on the screen.
   */
  function restsOnGrid(text: SVGTextElement, lands: DOMMatrix | null) {
    if (!lands) return false;
    const dpr = window.devicePixelRatio;
    const style = getComputedStyle(text);
    const k = lands.d * dpr;
    const y = text.y.baseVal.numberOfItems
      ? text.y.baseVal.getItem(0).value
      : 0;
    return (
      text.y.baseVal.numberOfItems <= 1 &&
      text.dy.baseVal.numberOfItems === 0 &&
      !text.querySelector("tspan[y], tspan[dy], textPath") &&
      /^(auto|alphabetic)$/.test(style.dominantBaseline) &&
      /^(auto|baseline)$/.test(style.alignmentBaseline) &&
      Math.abs(lands.b) < 1e-6 &&
      Math.abs(lands.c) < 1e-6 &&
      Math.round(k) >= 1 &&
      offWhole(k) < 2e-3 &&
      offWhole((lands.d * y + lands.f) * dpr) < ON_GRID
    );
  }

  /**
   * The angle that takes a block off the grid, given what is above it (`above`)
   * and what its own transform does (`own`), both in device pixels: the lean is
   * a turn between the two. 0 when the block leans enough as it is, null when
   * no sane angle would do.
   */
  function angleFor(above: Lin, own: Lin): number | null {
    // y from x of `above · turn(θ) · own` is p·sin θ + q·cos θ.
    const p = above[3] * own[0] - above[1] * own[1];
    const q = above[1] * own[0] + above[3] * own[1];
    if (Math.abs(q) >= LEAN) return 0;
    if (Math.abs(p) < 1e-9) return null;
    // Along the turn the scene already has, so the two never cancel out.
    const sine = ((q < 0 ? -LEAN : LEAN) - q) / p;
    if (Math.abs(sine) > Math.sin((STEEPEST * Math.PI) / 180)) return null;
    return (Math.asin(sine) * 180) / Math.PI;
  }

  function lean() {
    for (const el of leant) {
      el.style.removeProperty("rotate");
      if (el instanceof SVGElement) el.style.removeProperty("translate");
    }
    leant = [];
    const zones = document.querySelectorAll<HTMLElement | SVGElement>(MARKED);
    if (zones.length === 0) return;
    // Each block of text under a mark, and whether any transform above it moves.
    const blocks = new Map<Block, boolean>();
    // The texts a whole drawing leans for.
    const standsFor = new Map<SVGSVGElement, SVGTextElement[]>();
    for (const zone of zones) {
      const moving = zone.style.transform.includes(MOVING.trim());
      const walker = document.createTreeWalker(zone, NodeFilter.SHOW_TEXT);
      for (let node = walker.nextNode(); node; node = walker.nextNode()) {
        if (!/\S/.test(node.nodeValue ?? "")) continue;
        const block = blockOf(node);
        // A block that turns by a property of its own is left to the scene.
        if (!block || block.style.rotate) continue;
        blocks.set(block, moving || (blocks.get(block) ?? false));
        const text = node.parentElement?.closest("text");
        if (block instanceof SVGSVGElement && text instanceof SVGTextElement)
          standsFor.set(block, [...(standsFor.get(block) ?? []), text]);
      }
      watch(zone);
    }
    for (const block of blocks.keys()) watch(block);
    const dpr = window.devicePixelRatio;
    const scaled = (m: Lin): Lin => [
      m[0] * dpr,
      m[1] * dpr,
      m[2] * dpr,
      m[3] * dpr,
    ];
    // Outer blocks first: a block inside a leaning one takes only what it
    // still lacks, so leans never pile up. Everything is read before anything
    // is written; `given` stands in for the leans not yet on the page.
    const given = new Map<Element, number>();
    const { ownOf, linDown, carryDown } = reader(given);
    const writes: (() => void)[] = [];
    const ordered = [...blocks.keys()].sort((a, b) => depthOf(a) - depthOf(b));
    for (const el of ordered) {
      const moving = blocks.get(el) === true;
      if (el instanceof HTMLElement) {
        const above = linDown(el.parentElement);
        const mine = ownOf(el);
        if (!above || !mine) continue;
        if (!moving) {
          // Layout puts a baseline on a whole pixel wherever the box itself
          // sits, so text is on the grid when the transforms around it only
          // move it by whole pixels and show it one to one (or two, or three).
          const carry = carryDown(el);
          if (
            carry &&
            offWhole(carry.k * dpr) < 2e-3 &&
            offWhole(carry.dy * dpr) < ON_GRID
          )
            continue;
        }
        const angle = angleFor(scaled(above), mine.lin);
        if (!angle) continue;
        given.set(el, angle);
        writes.push(() => el.style.setProperty("rotate", `${angle}deg`));
        leant.push(el);
        continue;
      }
      if (el instanceof SVGSVGElement) {
        // A whole drawing: what it does itself is its own transform and the
        // scale of its viewBox, read off where it lands on the screen.
        const above = linDown(el.parentElement);
        const lands = el.getScreenCTM();
        const det = above ? above[0] * above[3] - above[1] * above[2] : 0;
        if (!above || !lands || Math.abs(det) < 1e-12) continue;
        if (
          !moving &&
          (standsFor.get(el) ?? []).every((text) =>
            restsOnGrid(text, text.getScreenCTM()),
          )
        )
          continue;
        const mine = times(
          [above[3] / det, -above[1] / det, -above[2] / det, above[0] / det],
          [lands.a, lands.b, lands.c, lands.d],
        );
        const angle = angleFor(scaled(above), mine);
        if (!angle) continue;
        given.set(el, angle);
        writes.push(() => el.style.setProperty("rotate", `${angle}deg`));
        leant.push(el);
        continue;
      }
      // Its drawing leans as a whole already.
      let drawing = el.ownerSVGElement;
      while (drawing?.ownerSVGElement) drawing = drawing.ownerSVGElement;
      if (drawing && given.has(drawing)) continue;
      // Text in an SVG is placed wherever it is told to, so it is on the grid
      // only when its baseline happens to land on a whole pixel.
      const frame = el.parentNode;
      if (!(frame instanceof SVGGraphicsElement) || el.style.translate)
        continue;
      const outer = frame.getScreenCTM();
      const whole = el.getScreenCTM();
      if (
        !outer ||
        !whole ||
        Math.abs(outer.a * outer.d - outer.b * outer.c) < 1e-12
      )
        continue;
      // What the text element itself does, in the space it is placed in.
      const mine = outer.inverse().multiply(whole);
      if (!moving && restsOnGrid(el, whole)) continue;
      const angle = angleFor(scaled([outer.a, outer.b, outer.c, outer.d]), [
        mine.a,
        mine.b,
        mine.c,
        mine.d,
      ]);
      if (!angle) continue;
      // An SVG element turns about the corner of its drawing. A move brings
      // the turn to the middle of the text instead.
      const box = el.getBBox();
      const [cx, cy] = [box.x + box.width / 2, box.y + box.height / 2];
      const [px, py] = [
        mine.a * cx + mine.c * cy + mine.e,
        mine.b * cx + mine.d * cy + mine.f,
      ];
      const [cos, sin] = [turned(angle)[0], turned(angle)[1]];
      const [tx, ty] = [px - (px * cos - py * sin), py - (px * sin + py * cos)];
      writes.push(() => {
        el.style.setProperty("rotate", `${angle}deg`);
        el.style.setProperty("translate", `${tx}px ${ty}px`);
      });
      leant.push(el);
    }
    for (const write of writes) write();
  }

  const useFrameEffect =
    typeof window === "undefined" ? useEffect : useLayoutEffect;

  function useGlide() {
    // No dependencies: the lean follows whatever this frame laid out.
    useFrameEffect(lean);
    return glide;
  }

  const glide = (moving: boolean) => (moving ? MOVING : AT_REST);

  return useGlide;
})();

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

/**
 * The other way round: a count Remotion gives a component in the
 * composition's own frames, in 30 fps frames. A transition's presentation
 * gets its length that way (`presentationDurationInFrames`).
 */
function useSceneFrameCount(): (compositionFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (compositionFrames: number) => (compositionFrames * SCENE_FPS) / fps,
    [fps],
  );
}

// A component's schedule, kept apart from its drawing: which elements the
// animation has (an entry, a word, a finale), when each starts and how long
// it runs. The schedule is a pure function of the props, so it can be read
// without rendering anything, and a `timing` prop can move, trim or stretch
// single elements without touching the code that draws them.
//
//   // timeline.ts, next to the component
//   export const titleTimeline = defineTimeline<TitleElementId, TitleProps>(
//     ({ words = WORDS }, { length }) =>
//       words.map((word, k) => ({
//         id: `word:${k}`,
//         lane: "Words",
//         label: word,
//         start: k * 8,
//         length: 8,
//         follows: k > 0 ? `word:${k - 1}` : undefined,
//         beats: { rise: 12 },
//       })),
//   );
//
//   // index.tsx
//   const tl = useTimeline(titleTimeline, props, length, timing);
//   const word = tl.get("word:0");
//   interpolate(t, [word.start, word.start + word.beat("rise")], [0, 1]);
//
// Every number is in frames of the 30 fps scene timeline, after `delay` and
// `speed`: those still apply to the whole animation, `timing` works inside it.
// Element ids are public API: a saved `timing` refers to them, so an id once
// shipped keeps its meaning.

/** One timed part of an animation, as its schedule lays it out. */
interface TimelineElement<Id extends string = string> {
  /** Stable name a `timing` override refers to: `entry:0`, `finale`. */
  id: Id;
  /** Row the element sits on in a timeline view. */
  lane: string;
  /** What the element shows, for people reading the timeline. */
  label: string;
  /** First frame of the element. */
  start: number;
  /** Frames until the next element of the lane takes over, or the end. */
  length: number;
  /**
   * The element this one comes after. When that element's end moves, this
   * one moves with it, keeping the gap between them.
   */
  follows?: Id;
  /**
   * Named frame counts inside the element, measured from its start: how long
   * a roll takes, when a second part begins. `stretch` scales them.
   */
  beats?: Record<string, number>;
}

/** A change to one element, made from outside the component. */
interface TimingOverride {
  /** New first frame. Wins over the shift from `follows`. */
  start?: number;
  /** New length, trimming or extending the element. Wins over `stretch`. */
  length?: number;
  /** Multiplies the length and every beat: 2 plays the element half as fast. */
  stretch?: number;
  /** Stops following: the element keeps its own start when the one before moves. */
  detach?: boolean;
}

/** Overrides by element id: the `timing` prop of a component. */
type Timing<Id extends string = string> = Partial<
  Record<Id, TimingOverride>
>;

/** A component's schedule: props and the scene length in, elements out. */
type Schedule<Id extends string, Props> = (
  props: Props,
  scene: { length: number },
) => TimelineElement<Id>[];

/** An element after `timing` has been applied. */
interface ResolvedElement<Id extends string = string>
  extends TimelineElement<Id> {
  /** `start + length`. */
  end: number;
  beats: Record<string, number>;
  /** A beat by name, stretched. Throws on a name the schedule didn't set. */
  beat(name: string): number;
  /**
   * 0 → 1 over the element, or over its first `beat` frames when a beat is
   * named. Clamped on both sides.
   */
  progress(frame: number, beat?: string): number;
}

interface ResolvedTimeline<Id extends string = string> {
  /** All elements, in the order the schedule returned them. */
  elements: ResolvedElement<Id>[];
  /** An element by id. Throws on an id the schedule didn't return. */
  get(id: Id): ResolvedElement<Id>;
  /** The elements of one lane, in order. */
  lane(name: string): ResolvedElement<Id>[];
}

/** Declares a schedule. Elements come back in time order. */
function defineTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
): Schedule<Id, Props> {
  return schedule;
}

/** Applies `timing` to a schedule's elements and carries the `follows` chains. */
function resolve<Id extends string>(
  elements: TimelineElement<Id>[],
  timing: Timing<Id> = {},
): ResolvedTimeline<Id> {
  const byId = new Map<Id, TimelineElement<Id>>(elements.map((e) => [e.id, e]));
  const done = new Map<Id, ResolvedElement<Id>>();
  const visiting = new Set<Id>();

  const place = (element: TimelineElement<Id>): ResolvedElement<Id> => {
    const known = done.get(element.id);
    if (known) return known;
    if (visiting.has(element.id)) {
      throw new Error(`timeline: "${element.id}" follows itself`);
    }
    visiting.add(element.id);

    const override: TimingOverride = timing[element.id] ?? {};
    const stretch = override.stretch ?? 1;
    const beats: Record<string, number> = {};
    for (const [name, frames] of Object.entries(element.beats ?? {})) {
      beats[name] = frames * stretch;
    }

    let start = element.start;
    const leader = element.follows ? byId.get(element.follows) : undefined;
    if (leader && !override.detach) {
      // The leader's end moved by this much; this element moves as far.
      start += place(leader).end - (leader.start + leader.length);
    }
    if (override.start !== undefined) start = override.start;
    const length = override.length ?? element.length * stretch;

    const beat = (name: string) => {
      const frames = beats[name];
      if (frames === undefined) {
        throw new Error(`timeline: "${element.id}" has no beat "${name}"`);
      }
      return frames;
    };
    const resolved: ResolvedElement<Id> = {
      ...element,
      start,
      length,
      end: start + length,
      beats,
      beat,
      progress: (frame, name) => {
        const span = name === undefined ? length : beat(name);
        if (span <= 0) return frame >= start ? 1 : 0;
        return Math.min(1, Math.max(0, (frame - start) / span));
      },
    };
    visiting.delete(element.id);
    done.set(element.id, resolved);
    return resolved;
  };

  const all = elements.map(place);
  return {
    elements: all,
    get: (id) => {
      const element = done.get(id);
      if (!element) throw new Error(`timeline: no element "${id}"`);
      return element;
    },
    lane: (name) => all.filter((e) => e.lane === name),
  };
}

/**
 * The component side: runs the schedule and applies `timing`, once per
 * change of its inputs. `length` is the scene length the schedule fits into,
 * in the same frames the component counts.
 */
function useTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
  props: Props,
  length: number,
  timing?: Timing<Id>,
): ResolvedTimeline<Id> {
  return useMemo(
    () => resolve(schedule(props, { length }), timing),
    [schedule, props, length, timing],
  );
}

// The launch date: the month drawing itself as hairlines while the header
// and the day numbers settle, the days lighting up in a sweep to the launch
// day, a slow push onto it while a stroke circles it, then the grid falling
// away as the day slides into a big date lockup, the circle tightening into
// its full stop and echoing out as a halo, the other half of the date and
// the label landing over a long drift. Frames on the 30 fps scene timeline,
// after `delay` and `speed`. The ids are public: a saved `timing` prop
// refers to them.

type LaunchDateElementId =
  | "lines"
  | "settle"
  | "header"
  | "days"
  | "sweep"
  | "push"
  | "circle"
  | "fall"
  | "drift"
  | "hand"
  | "stop"
  | "echo"
  | "other"
  | "label";

/** The date as the schedule reads it (`LaunchDateValue`). */
interface LaunchDay {
  month: number;
  day: number;
  year: number;
}

interface LaunchDateTimingProps {
  date?: LaunchDay;
}

const DEFAULT_LAUNCH_DATE: LaunchDay = {
  month: 10,
  day: 30,
  year: 2026,
};

/** Day of week, 0 = Monday (Sakamoto). Pure arithmetic, no Date. */
function weekdayOf(year: number, month: number, day: number) {
  const t = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4];
  const y = month < 3 ? year - 1 : year;
  const sun0 =
    (y +
      Math.floor(y / 4) -
      Math.floor(y / 100) +
      Math.floor(y / 400) +
      t[month - 1] +
      day) %
    7;
  return (sun0 + 6) % 7;
}

function daysInMonth(year: number, month: number) {
  if (month === 2) {
    const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
    return leap ? 29 : 28;
  }
  return [4, 6, 9, 11].includes(month) ? 30 : 31;
}

// `lines` draws the grid: row line `r` at `r` × `stagger`, column line `c`
// at `colsAt` + `c` × `stagger`, each over `draw`. `settle` eases the camera
// in, `push` pushes it onto the launch day and `drift` keeps it creeping
// over the hold; they form a chain. `header` brings the month header in over
// its length and fades it from `outAt` to `out`. `days` brings row `r` of
// the day numbers in at `r` × `row` over `fade`. `sweep` lights day `d` at
// `d - 1` × `step` frames, flashing to `flashPeak` and back by `flash`, its
// lit state over `lit`. `circle` draws the stroke around the day. `fall`
// drops each cell `ripple` frames per cell of distance from the launch day
// over `drop`, the grid lines fading from `linesAt` to `lines`. `hand`
// slides the day into the lockup, `stop` tightens the circle into the full
// stop (filling from `closeAt` to `close`), `echo` rings it out (fading in
// over `fade`, the halo turning until `spin`), `other` brings the other half
// of the date in, and `label` rises line `k` at `k` × `stagger` over `rise`.
const launchDateTimeline = defineTimeline<
  LaunchDateElementId,
  LaunchDateTimingProps
>(({ date = DEFAULT_LAUNCH_DATE }): TimelineElement<LaunchDateElementId>[] => {
  const month = Math.min(12, Math.max(1, Math.round(date.month)));
  const total = daysInMonth(date.year, month);
  const launchDay = Math.min(total, Math.max(1, Math.round(date.day)));
  const lead = weekdayOf(date.year, month, 1);
  const rows = Math.ceil((lead + total) / 7);
  const step = 28 / Math.max(1, launchDay);
  return [
    {
      id: "lines",
      lane: "Grid",
      label: "hairlines",
      start: 0,
      length: Math.max(rows * 2, 4 + 6 * 2) + 16,
      beats: { stagger: 2, colsAt: 4, draw: 16 },
    },
    { id: "settle", lane: "Camera", label: "settle", start: 0, length: 20 },
    {
      id: "header",
      lane: "Header",
      label: "header",
      start: 4,
      length: 22,
      beats: { outAt: 56, out: 80 },
    },
    {
      id: "days",
      lane: "Days",
      label: "days",
      start: 8,
      length: (rows - 1) * 2.5 + 16,
      beats: { row: 2.5, fade: 16 },
    },
    {
      id: "sweep",
      lane: "Days",
      label: "sweep",
      start: 16,
      length: (launchDay - 1) * step + 14,
      beats: { step, flashPeak: 3, flash: 14, lit: 10 },
    },
    {
      id: "push",
      lane: "Camera",
      label: "push",
      start: 20,
      length: 70,
      follows: "settle",
    },
    { id: "circle", lane: "Circle", label: "circle", start: 64, length: 26 },
    {
      id: "fall",
      lane: "Grid",
      label: "fall away",
      start: 90,
      length: 18,
      beats: { ripple: 2.2, drop: 18, linesAt: -4, lines: 14 },
    },
    {
      id: "drift",
      lane: "Camera",
      label: "drift",
      start: 90,
      length: 105,
      follows: "push",
    },
    {
      id: "hand",
      lane: "Lockup",
      label: "day to lockup",
      start: 92,
      length: 28,
    },
    {
      id: "stop",
      lane: "Circle",
      label: "full stop",
      start: 114,
      length: 22,
      beats: { closeAt: 10, close: 20 },
    },
    {
      id: "echo",
      lane: "Circle",
      label: "echo",
      start: 124,
      length: 40,
      follows: "stop",
      beats: { fade: 6, spin: 71 },
    },
    {
      id: "other",
      lane: "Lockup",
      label: "other half",
      start: 128,
      length: 24,
      follows: "hand",
    },
    {
      id: "label",
      lane: "Label",
      label: "label",
      start: 140,
      length: 6 + 24,
      follows: "other",
      beats: { stagger: 3, rise: 24 },
    },
  ];
});

const { fontFamily: sora } = loadFont("normal", {
  weights: ["300", "400", "500"],
  subsets: ["latin"],
});

/**
 * gradients.sh "halo" palette: [#fff4ec, #ffb36b, #e2457a, #3d4dff]. The ring
 * that circles the day is drawn in it, tightens into a full stop that keeps
 * it, and leaves a soft halo ring behind the lockup. The blue end is the
 * accent, so the palette lands on the brand.
 */
const HALO = ["#fff4ec", "#ffb36b", "#e2457a", "#3d4dff"] as const;

/**
 * Beat sheet (30fps, speed 1):
 * 0–30     the month draws itself as hairlines; header and day numbers settle.
 * 14–44    days light up in a quick sweep from the 1st to the launch day.
 * 30–88    slow eased push toward the launch day; the rest of the grid
 *          drifts out of focus.
 * 66–90    an accent stroke circles the day.
 * 92–124   the grid falls away; the day slides into a huge "10.30" lockup
 *          while the circle tightens into the accent full stop.
 * 120–180  label lands, long hold.
 */

interface LaunchDateValue {
  /** 1–12. */
  month: number;
  day: number;
  year: number;
}

interface LaunchDateProps {
  date?: LaunchDateValue;
  /** Short line under the lockup. */
  label?: string;
  /** "month-day" renders 10.30, "day-month" renders 30.10. */
  order?: "month-day" | "day-month";
  accent?: string;
  /** Text color; overrides the theme ink. */
  ink?: string;
  /** Background fill; "transparent" drops it. */
  background?: string;
  /** Typeface for the copy. Load it yourself; Sora by default. */
  fontFamily?: string;
  /** Weight of the day numbers and the date lockup. */
  fontWeight?: number;
  /** Size of the foreground, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  grain?: boolean;
  /** Playback multiplier. */
  speed?: number;
  theme?: "dark" | "light";
  /**
   * Moves, trims or stretches the grid, the camera, the header, the days,
   * the sweep, the circle, the fall, the lockup and the label, by the ids in
   * `./timeline`. Frames on the scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<LaunchDateElementId>;
}

const MONTHS = [
  "January",
  "February",
  "March",
  "April",
  "May",
  "June",
  "July",
  "August",
  "September",
  "October",
  "November",
  "December",
];
const WEEKDAYS = [
  "Monday",
  "Tuesday",
  "Wednesday",
  "Thursday",
  "Friday",
  "Saturday",
  "Sunday",
];

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_PUSH = Easing.bezier(0.5, 0, 0.3, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IN = Easing.bezier(0.55, 0, 0.9, 0.4);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const PALETTES = {
  dark: {
    bg: "#0A0A0B",
    stage: "rgba(255,255,255,0.055)",
    fg: "#F3F2EF",
    muted: "#85848A",
    faint: "#4A4A50",
    line: "rgba(255,255,255,0.13)",
    lit: "rgba(255,255,255,0.075)",
    grain: 0.065,
    /** Peak opacity of the halo behind the lockup. */
    halo: 1,
    /** Halo ring stops, top-left → bottom-right, before the accent. */
    haloStops: [HALO[0], HALO[1], HALO[2]],
  },
  light: {
    bg: "#F5F4F0",
    stage: "rgba(255,255,255,0.85)",
    fg: "#121214",
    muted: "#6E6C67",
    faint: "#B9B6AE",
    line: "rgba(18,18,20,0.13)",
    lit: "rgba(18,18,20,0.05)",
    grain: 0.045,
    halo: 0.9,
    haloStops: [HALO[1], HALO[1], HALO[2]],
  },
} as const;

type Palette = (typeof PALETTES)[keyof typeof PALETTES];

const pad = (n: number) => String(n).padStart(2, "0");

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={11}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

interface CellProps {
  t: number;
  days: ResolvedElement<LaunchDateElementId>;
  sweep: ResolvedElement<LaunchDateElementId>;
  fall: ResolvedElement<LaunchDateElementId>;
  day: number;
  col: number;
  row: number;
  cellW: number;
  cellH: number;
  hero: boolean;
  launchDay: number;
  heroRow: number;
  heroCol: number;
  p: Palette;
  u: number;
  fg: string;
  fontFamily: string;
  fontWeight: number;
}

function DayCell({
  t,
  days,
  sweep,
  fall: fallEl,
  day,
  col,
  row,
  cellW,
  cellH,
  hero,
  launchDay,
  heroRow,
  heroCol,
  p,
  u,
  fg,
  fontFamily,
  fontWeight,
}: CellProps) {
  // settle in with the grid
  const at = days.start + row * days.beat("row");
  const appear = interpolate(t, [at, at + days.beat("fade")], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  // sweep: day 1 → launch day across ~28 frames
  const hit = sweep.start + (day - 1) * sweep.beat("step");
  const swept = day <= launchDay;
  const flash = swept
    ? interpolate(
        t,
        [hit, hit + sweep.beat("flashPeak"), hit + sweep.beat("flash")],
        [0, 1, 0],
        CLAMP,
      )
    : 0;
  const after = swept
    ? interpolate(t, [hit, hit + sweep.beat("lit")], [0, 1], CLAMP)
    : 0;
  const numO = appear * (0.38 + 0.62 * flash + 0.22 * after * (1 - flash));
  // fall away: ripple outward from the launch day
  const dist = Math.hypot(col - heroCol, (row - heroRow) * 1.3);
  const f0 = fallEl.start + dist * fallEl.beat("ripple");
  const fall = interpolate(t, [f0, f0 + fallEl.beat("drop")], [0, 1], {
    ...CLAMP,
    easing: EASE_IN,
  });
  return (
    <div
      style={{
        position: "absolute",
        left: col * cellW,
        top: row * cellH,
        width: cellW,
        height: cellH,
        transform: `perspective(${900 * u}px) translateY(${fall * cellH * 0.9}px) rotateX(${-fall * 55}deg)`,
        transformOrigin: "50% 100%",
        opacity: 1 - fall,
      }}
    >
      <div
        style={{
          position: "absolute",
          inset: 1.5 * u,
          borderRadius: 6 * u,
          background: p.lit,
          opacity: flash + (hero ? after * 0.9 : after * 0.25),
        }}
      />
      {hero ? null : (
        <div
          style={{
            position: "absolute",
            inset: 0,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            fontFamily,
            fontWeight,
            fontSize: cellH * 0.3,
            fontVariantNumeric: "tabular-nums",
            letterSpacing: "-0.02em",
            color: fg,
            opacity: numO,
          }}
        >
          {day}
        </div>
      )}
    </div>
  );
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function LaunchDateBase(props: LaunchDateProps) {
  const {
    date = DEFAULT_LAUNCH_DATE,
    label = "Coming soon",
    order = "month-day",
    accent = "#3B5BFD",
    ink,
    background,
    fontFamily = sora,
    fontWeight = 300,
    scale = 1,
    delay = 0,
    grain = true,
    speed = 1,
    theme = "dark",
    timing,
  } = props;
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width, height, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    launchDateTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const linesEl = tl.get("lines");
  const settleEl = tl.get("settle");
  const headerEl = tl.get("header");
  const daysEl = tl.get("days");
  const sweepEl = tl.get("sweep");
  const pushEl = tl.get("push");
  const circleEl = tl.get("circle");
  const fallEl = tl.get("fall");
  const driftEl = tl.get("drift");
  const handEl = tl.get("hand");
  const stopEl = tl.get("stop");
  const echoEl = tl.get("echo");
  const otherEl = tl.get("other");
  const labelEl = tl.get("label");
  const u = height / 720;
  const p: Palette = PALETTES[theme];
  const fg = ink ?? p.fg;

  const month = Math.min(12, Math.max(1, Math.round(date.month)));
  const total = daysInMonth(date.year, month);
  const launchDay = Math.min(total, Math.max(1, Math.round(date.day)));
  const lead = weekdayOf(date.year, month, 1);
  const rows = Math.ceil((lead + total) / 7);

  // ---- calendar layout (grid space, origin at the grid's top-left) ----
  const cellH = Math.min(height * 0.64, height) / (rows + 1.7);
  const cellW = Math.min(cellH * 1.38, (width * 0.62) / 7);
  const gridW = cellW * 7;
  const headH = cellH * 1.1;
  const dowH = cellH * 0.6;
  const gridH = headH + dowH + rows * cellH;
  const bodyTop = headH + dowH;
  const heroIdx = lead + launchDay - 1;
  const heroCol = heroIdx % 7;
  const heroRow = Math.floor(heroIdx / 7);
  const heroGX = (heroCol + 0.5) * cellW;
  const heroGY = bodyTop + (heroRow + 0.5) * cellH;

  // ---- camera: screen = C + (g - F) * s ----
  const cx = width / 2;
  const cy = height * 0.5;
  const push = interpolate(t, [pushEl.start, pushEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_PUSH,
  });
  const S = 2.5;
  const s =
    interpolate(push, [0, 1], [0.94, S]) *
    interpolate(t, [settleEl.start, settleEl.end], [0.97, 1], CLAMP);
  const fx = interpolate(push, [0, 1], [gridW / 2, heroGX]);
  const fy = interpolate(push, [0, 1], [gridH / 2, heroGY]);
  const toScreen = (gx: number, gy: number) => ({
    x: cx + (gx - fx) * s,
    y: cy + (gy - fy) * s,
  });
  const gridOrigin = toScreen(0, 0);
  // Where the camera leaves the grid once the push lands. The grid is laid
  // out there and the camera's travel is a transform: layout rounds a box and
  // a baseline to whole pixels, so a grid eased by `left`/`top` steps.
  const gridRestX = cx - heroGX * S;
  const gridRestY = cy - heroGY * S;
  const dof = interpolate(push, [0.35, 1], [0, 2.4 * u], CLAMP);
  const linesOut = interpolate(
    t,
    [
      fallEl.start + fallEl.beat("linesAt"),
      fallEl.start + fallEl.beat("lines"),
    ],
    [1, 0],
    CLAMP,
  );
  const headOut = interpolate(
    t,
    [
      headerEl.start + headerEl.beat("outAt"),
      headerEl.start + headerEl.beat("out"),
    ],
    [1, 0],
    CLAMP,
  );

  // ---- lockup (screen space) ----
  const F = Math.min(height * 0.34, (width * 0.7) / 2.7);
  const groupW = F * 1.14;
  const dotW = F * 0.27;
  const lockW = groupW * 2 + dotW;
  const lockCY = height * 0.45;
  const lockLeft = cx - lockW / 2;
  const dayFirst = order === "day-month";
  const daySlotX = dayFirst
    ? lockLeft + groupW / 2
    : lockLeft + lockW - groupW / 2;
  const dotD = F * 0.135;
  const dotX = cx;
  const dotY = lockCY + F * 0.364 - dotD / 2;

  // hero day: follows its cell, then glides to the lockup slot
  const hand = interpolate(t, [handEl.start, handEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const heroCell = toScreen(heroGX, heroGY);
  const heroFont0 = cellH * 0.3 * s;
  const heroX = interpolate(hand, [0, 1], [heroCell.x, daySlotX]);
  const heroY = interpolate(hand, [0, 1], [heroCell.y, lockCY]);
  const heroFont = interpolate(hand, [0, 1], [heroFont0, F]);
  const heroWeight = fontWeight;
  // The day is laid out once at its lockup size and slot; the ride there and
  // the growth are a transform, for the same reason as the grid.
  const heroK = heroFont / F;
  const heroTrack = interpolate(hand, [0, 1], [-0.02, -0.06]);
  const heroAt = daysEl.start + heroRow * daysEl.beat("row");
  const heroAppear = interpolate(
    t,
    [heroAt, heroAt + daysEl.beat("fade")],
    [0, 1],
    { ...CLAMP, easing: EASE_OUT },
  );
  const heroHit = sweepEl.start + (launchDay - 1) * sweepEl.beat("step");
  const heroLit = interpolate(
    t,
    [heroHit, heroHit + sweepEl.beat("flashPeak")],
    [0.38, 1],
    CLAMP,
  );

  // circle: draws around the day, rides along with it, then tightens into
  // the full stop of the lockup
  const draw = interpolate(t, [circleEl.start, circleEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const ringW0 = Math.max(2, 2.5 * u * (s / S));
  const rideR = heroFont * interpolate(hand, [0, 1], [1.2, 0.7]);
  const rideW = ringW0 * interpolate(hand, [0, 1], [1, 1.7]);
  const shrink = interpolate(t, [stopEl.start, stopEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  // stays a hairline while it tightens, fills only once it is dot-sized
  const close = interpolate(
    t,
    [
      stopEl.start + stopEl.beat("closeAt"),
      stopEl.start + stopEl.beat("close"),
    ],
    [0, 1],
    {
      ...CLAMP,
      easing: EASE_IO,
    },
  );
  const outerR = interpolate(shrink, [0, 1], [rideR + rideW / 2, dotD / 2]);
  const ringW = Math.min(outerR, interpolate(close, [0, 1], [rideW, outerR]));
  const ringR = outerR - ringW / 2;
  const ringX = interpolate(shrink, [0, 1], [heroX, dotX]);
  const ringY = interpolate(shrink, [0, 1], [heroY, dotY]);
  const ringBox = ringR + ringW + 4;
  const circ = 2 * Math.PI * ringR;
  const ringId = `ring${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;

  // the echo: as the full stop lands, the ring it came from rings out once
  // more, wide, and stays behind the lockup as a halo of the same light
  const echo = interpolate(t, [echoEl.start, echoEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const echoR = dotD / 2 + (height * 0.37 - dotD / 2) * echo;
  const echoO = interpolate(
    t,
    [echoEl.start, echoEl.start + echoEl.beat("fade")],
    [0, 1],
    CLAMP,
  );
  const haloSpin = interpolate(
    t,
    [echoEl.start, echoEl.start + echoEl.beat("spin")],
    [-30, 10],
    CLAMP,
  );
  const haloId = `halo${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  const blurId = `hb${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;

  // the other half of the lockup
  const other = interpolate(t, [otherEl.start, otherEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const labelP = (k: number) => {
    const at = labelEl.start + k * labelEl.beat("stagger");
    return interpolate(t, [at, at + labelEl.beat("rise")], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
  };
  const labelTop = lockCY + F * 0.5 + 40 * u;
  const otherValue = pad(month);
  const fullDate = `${WEEKDAYS[weekdayOf(date.year, month, launchDay)]}, ${MONTHS[month - 1]} ${launchDay}, ${date.year}`;

  const lines: React.ReactNode[] = [];
  for (let r = 0; r <= rows; r++) {
    const d = linesEl.start + r * linesEl.beat("stagger");
    const k = interpolate(t, [d, d + linesEl.beat("draw")], [0, 1], {
      ...CLAMP,
      easing: EASE_IO,
    });
    lines.push(
      <div
        key={`h${r}`}
        style={{
          position: "absolute",
          left: 0,
          top: bodyTop + r * cellH,
          width: gridW,
          height: Math.max(1, u),
          background: p.line,
          transformOrigin: "0 50%",
          transform: `scaleX(${k})`,
        }}
      />,
    );
  }
  for (let c = 1; c < 7; c++) {
    const d =
      linesEl.start + linesEl.beat("colsAt") + c * linesEl.beat("stagger");
    const k = interpolate(t, [d, d + linesEl.beat("draw")], [0, 1], {
      ...CLAMP,
      easing: EASE_IO,
    });
    lines.push(
      <div
        key={`v${c}`}
        style={{
          position: "absolute",
          left: c * cellW,
          top: bodyTop,
          width: Math.max(1, u),
          height: rows * cellH,
          background: p.line,
          transformOrigin: "50% 0",
          transform: `scaleY(${k})`,
        }}
      />,
    );
  }

  const cells: React.ReactNode[] = [];
  for (let d = 1; d <= total; d++) {
    const i = lead + d - 1;
    cells.push(
      <DayCell
        key={d}
        t={t}
        days={daysEl}
        sweep={sweepEl}
        fall={fallEl}
        day={d}
        col={i % 7}
        row={Math.floor(i / 7)}
        cellW={cellW}
        cellH={cellH}
        hero={d === launchDay}
        launchDay={launchDay}
        heroRow={heroRow}
        heroCol={heroCol}
        p={p}
        u={u}
        fg={fg}
        fontFamily={fontFamily}
        fontWeight={fontWeight}
      />,
    );
  }

  // a slow push that never quite stops, so the hold stays alive
  const drift = interpolate(t, [driftEl.start, driftEl.end], [1, 1.035], CLAMP);
  // The camera moves until 90 and the drift takes over from there, so the
  // whole foreground is in motion from the first frame to the last.
  const moving = t > 0 && t < driftEl.end;
  const headIn = interpolate(t, [headerEl.start, headerEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  return (
    <AbsoluteFill
      style={{
        background:
          background === "transparent" ? undefined : (background ?? p.bg),
        overflow: "hidden",
      }}
    >
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 60% 70% at 50% 40%, ${p.stage}, transparent 75%)`,
        }}
      />

      <ScaleLayer scale={scale}>
        <AbsoluteFill style={{ transform: `scale(${drift})${glide(moving)}` }}>
          {echoO > 0 ? (
            <svg
              width={width}
              height={height}
              style={{ position: "absolute", inset: 0, overflow: "visible" }}
              aria-hidden
            >
              <defs>
                <linearGradient
                  id={haloId}
                  gradientUnits="userSpaceOnUse"
                  x1={dotX - echoR}
                  y1={lockCY - echoR}
                  x2={dotX + echoR}
                  y2={lockCY + echoR}
                  gradientTransform={`rotate(${haloSpin} ${dotX} ${lockCY})`}
                >
                  <stop offset="0%" stopColor={p.haloStops[0]} />
                  <stop offset="38%" stopColor={p.haloStops[1]} />
                  <stop offset="70%" stopColor={p.haloStops[2]} />
                  <stop offset="100%" stopColor={accent} />
                </linearGradient>
                <filter
                  id={blurId}
                  x="-50%"
                  y="-50%"
                  width="200%"
                  height="200%"
                >
                  <feGaussianBlur stdDeviation={16 * u} />
                </filter>
              </defs>
              <g opacity={echoO * p.halo}>
                <circle
                  cx={dotX}
                  cy={lockCY}
                  r={echoR}
                  fill="none"
                  stroke={`url(#${haloId})`}
                  strokeWidth={34 * u}
                  filter={`url(#${blurId})`}
                  opacity={0.55}
                />
                <circle
                  cx={dotX}
                  cy={lockCY}
                  r={echoR}
                  fill="none"
                  stroke={`url(#${haloId})`}
                  strokeWidth={interpolate(echo, [0, 1], [4, 1.6]) * u}
                />
              </g>
            </svg>
          ) : null}
          {/* the month, in grid space under the camera */}
          <div
            style={{
              position: "absolute",
              left: gridRestX,
              top: gridRestY,
              width: gridW,
              height: gridH,
              transformOrigin: "0 0",
              transform: `translate(${gridOrigin.x - gridRestX}px, ${gridOrigin.y - gridRestY}px) scale(${s})`,
              filter: dof > 0.05 ? `blur(${dof / s}px)` : undefined,
            }}
          >
            <div
              style={{
                position: "absolute",
                left: cellW * 0.12,
                right: cellW * 0.12,
                top: 0,
                height: headH,
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                opacity: headIn * headOut,
                transform: `translateY(${(1 - headIn) * 10 * u}px)`,
              }}
            >
              <span
                style={{
                  fontFamily,
                  fontWeight: 500,
                  fontSize: cellH * 0.5,
                  letterSpacing: "-0.04em",
                  color: fg,
                }}
              >
                {MONTHS[month - 1]}
              </span>
              <span
                style={{
                  fontFamily,
                  fontWeight: 400,
                  fontSize: cellH * 0.3,
                  letterSpacing: "-0.02em",
                  fontVariantNumeric: "tabular-nums",
                  color: p.muted,
                }}
              >
                {date.year}
              </span>
            </div>
            <div
              style={{
                position: "absolute",
                left: 0,
                top: headH,
                width: gridW,
                height: dowH,
                display: "flex",
                opacity: headIn * headOut,
              }}
            >
              {WEEKDAYS.map((w, i) => (
                <div
                  key={w}
                  style={{
                    width: cellW,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    fontFamily,
                    fontWeight: 400,
                    fontSize: cellH * 0.17,
                    letterSpacing: "0.1em",
                    textTransform: "uppercase",
                    color: i > 4 ? p.faint : p.muted,
                  }}
                >
                  {w.slice(0, 3)}
                </div>
              ))}
            </div>
            <div style={{ position: "absolute", inset: 0, opacity: linesOut }}>
              {lines}
            </div>
            <div style={{ position: "absolute", left: 0, top: bodyTop }}>
              {cells}
            </div>
          </div>

          {/* accent ring → full stop */}
          <svg
            width={ringBox * 2}
            height={ringBox * 2}
            viewBox={`${-ringBox} ${-ringBox} ${ringBox * 2} ${ringBox * 2}`}
            style={{
              position: "absolute",
              left: ringX - ringBox,
              top: ringY - ringBox,
              overflow: "visible",
            }}
            aria-hidden
          >
            <defs>
              <linearGradient
                id={ringId}
                gradientUnits="userSpaceOnUse"
                x1={-ringBox}
                y1={-ringBox}
                x2={ringBox}
                y2={ringBox}
              >
                <stop offset="8%" stopColor={HALO[1]} />
                <stop offset="50%" stopColor={HALO[2]} />
                <stop offset="92%" stopColor={accent} />
              </linearGradient>
            </defs>
            <circle
              r={ringR}
              fill="none"
              stroke={`url(#${ringId})`}
              strokeWidth={ringW}
              strokeLinecap="round"
              strokeDasharray={circ}
              strokeDashoffset={circ * (1 - draw)}
              transform="rotate(-118)"
            />
          </svg>

          {/* the launch day, in screen space so it can leave the grid */}
          <div
            style={{
              position: "absolute",
              left: daySlotX - F * 2,
              top: lockCY - F,
              width: F * 4,
              height: F * 2,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              fontFamily,
              fontWeight: heroWeight,
              fontSize: F,
              lineHeight: 1,
              letterSpacing: `${heroTrack}em`,
              fontVariantNumeric: "tabular-nums",
              color: fg,
              opacity: heroAppear * heroLit,
              transform:
                hand < 1
                  ? `translate(${heroX - daySlotX}px, ${heroY - lockCY}px) scale(${heroK})${glide(t > 0)}`
                  : undefined,
              // the filter is drawn before the scale, so its radius is undone
              filter:
                dof > 0.05 && hand < 0.01
                  ? `blur(${(dof * 0.15) / heroK}px)`
                  : undefined,
            }}
          >
            {pad(launchDay)}
          </div>

          {/* the other half of the lockup, revealed from behind the full stop */}
          <div
            style={{
              position: "absolute",
              left: dayFirst ? cx + dotW / 2 : lockLeft,
              top: lockCY - F,
              width: groupW,
              height: F * 2,
              overflow: "hidden",
            }}
          >
            <div
              style={{
                position: "absolute",
                inset: 0,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                fontFamily,
                fontWeight,
                fontSize: F,
                lineHeight: 1,
                letterSpacing: "-0.06em",
                fontVariantNumeric: "tabular-nums",
                color: fg,
                opacity: other,
                transform: `translateX(${(dayFirst ? -1 : 1) * (1 - other) * groupW * 0.55}px)`,
              }}
            >
              {otherValue}
            </div>
          </div>

          {/* label */}
          <div
            style={{
              position: "absolute",
              left: 0,
              right: 0,
              top: labelTop,
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              gap: 16 * u,
              fontFamily,
              fontSize: 21 * u,
              lineHeight: 1,
            }}
          >
            <span
              style={{
                color: fg,
                fontWeight: 500,
                letterSpacing: "-0.02em",
                opacity: labelP(0),
                transform: `translateY(${(1 - labelP(0)) * 12 * u}px)`,
              }}
            >
              {label}
            </span>
            <div
              style={{
                width: Math.max(1, u),
                height: 20 * u,
                background: p.line,
                transform: `scaleY(${labelP(1)})`,
              }}
            />
            <span
              style={{
                color: p.muted,
                fontWeight: 400,
                letterSpacing: "-0.015em",
                fontVariantNumeric: "tabular-nums",
                opacity: labelP(2),
                transform: `translateY(${(1 - labelP(2)) * 12 * u}px)`,
              }}
            >
              {fullDate}
            </span>
          </div>
        </AbsoluteFill>
      </ScaleLayer>
      {grain ? <Grain opacity={p.grain} /> : null}
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  label: {
    type: "text-content",
    default: "Coming soon",
    description: "Label",
  },
  order: {
    type: "enum",
    default: "month-day",
    variants: {
      "month-day": {},
      "day-month": {},
    },
    description: "Order",
  },
  fontWeight: {
    type: "number",
    default: 300,
    min: 100,
    max: 800,
    step: 100,
    description: "Weight",
    hiddenFromList: false,
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  fontFamily: {
    type: "font-family",
    default: "Sora",
    description: "Font",
  },
  ink: {
    type: "color",
    default: undefined,
    description: "Text color",
  },
  background: {
    type: "color",
    default: undefined,
    description: "Background",
  },
  scale: {
    type: "number",
    default: 1,
    min: 0.5,
    max: 1.5,
    step: 0.05,
    description: "Scale",
    hiddenFromList: false,
  },
  delay: {
    type: "number",
    default: 0,
    min: 0,
    max: 60,
    step: 1,
    description: "Delay (frames)",
    hiddenFromList: false,
  },
  grain: {
    type: "boolean",
    default: true,
    description: "Grain",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","label","order","fontWeight","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  label: "Coming soon",
  order: "month-day",
  fontWeight: 300,
  accent: "#3B5BFD",
  fontFamily: "Sora",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type LaunchDateElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof LaunchDateBase>;

const LaunchDateInner = forwardRef<
  HTMLDivElement,
  LaunchDateElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<LaunchDate>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <LaunchDateBase
          {...(componentProps as unknown as ComponentProps<typeof LaunchDateBase>)}
        />
      </div>
    </Sequence>
  );
});

export const LaunchDate = Interactive.withSchema({
  Component: LaunchDateInner,
  componentName: "<LaunchDate>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
